INSERT IGNORE INTO document_templates (template_key, template_name, html_content, footer_html, page_size, page_orientation, is_active) VALUES
('invoice', 'Invoice', '<table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong><br><span style="color:#555;font-size:9pt">{{company_address}}</span></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold">INVOICE</div><div style="font-size:13pt">#{{invoice_number}}</div></td></tr></table><table style="margin-bottom:16px"><tr><td style="width:50%"><div style="color:#555;font-size:9pt">BILL TO</div><strong>{{customer_name}}</strong><br>{{billing_address}}</td><td><div style="color:#555;font-size:9pt">SHIP TO</div><strong>{{ship_to_name}}</strong><br>{{ship_to_address}}</td></tr></table><table style="margin-bottom:12px;background:#f9f9f9;padding:8px"><tr><td><div style="color:#555;font-size:9pt">Invoice Date</div><strong>{{invoice_date}}</strong></td><td><div style="color:#555;font-size:9pt">Due Date</div><strong>{{due_date}}</strong></td><td><div style="color:#555;font-size:9pt">Terms</div>{{payment_terms}}</td><td><div style="color:#555;font-size:9pt">Ship Via</div>{{ship_via}}</td></tr></table><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0;border-bottom:2px solid #ccc"><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:right;padding:5px">Qty</th><th style="text-align:right;padding:5px">Price</th><th style="text-align:right;padding:5px">Extended</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="text-align:right;padding:5px">{{quantity}}</td><td style="text-align:right;padding:5px">${{unit_price}}</td><td style="text-align:right;padding:5px">${{extended}}</td></tr>{{/each}}</tbody></table><table style="width:40%;margin-left:auto;margin-top:12px"><tr><td>Subtotal</td><td style="text-align:right;font-weight:bold">${{subtotal}}</td></tr>{{#if freight_amount}}<tr><td>Freight</td><td style="text-align:right">${{freight_amount}}</td></tr>{{/if}}{{#if deposit_amount}}<tr><td>Less Deposit</td><td style="text-align:right">-${{deposit_amount}}</td></tr>{{/if}}<tr style="border-top:2px solid #333"><td style="font-weight:bold;font-size:12pt">Total Due</td><td style="text-align:right;font-weight:bold;font-size:12pt">${{total_due}}</td></tr></table>{{#if external_notes}}<div style="margin-top:20px;padding:8px;border:1px solid #e0e0e0"><div style="color:#555;font-size:9pt">Notes</div>{{external_notes}}</div>{{/if}}', '{{company_name}} | Invoice {{invoice_number}}', 'letter', 'portrait', 1),
('purchase_order', 'Purchase Order', '<table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong><br><span style="color:#555;font-size:9pt">{{company_address}}</span></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold">PURCHASE ORDER</div><div style="font-size:13pt">#{{po_number}}</div></td></tr></table><table style="margin-bottom:16px"><tr><td style="width:50%"><div style="color:#555;font-size:9pt">SUPPLIER</div><strong>{{supplier_name}}</strong></td><td><div style="color:#555;font-size:9pt">SHIP TO FACILITY</div><strong>{{facility_name}}</strong></td></tr></table><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0;border-bottom:2px solid #ccc"><th style="text-align:left;padding:5px">#</th><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:right;padding:5px">Qty</th><th style="text-align:right;padding:5px">Cost</th><th style="text-align:right;padding:5px">Total</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{line_num}}</td><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="text-align:right;padding:5px">{{quantity}}</td><td style="text-align:right;padding:5px">${{unit_cost}}</td><td style="text-align:right;padding:5px">${{line_total}}</td></tr>{{/each}}</tbody></table><table style="width:40%;margin-left:auto;margin-top:12px"><tr style="border-top:2px solid #333"><td style="font-weight:bold">Total</td><td style="text-align:right;font-weight:bold">${{po_total}}</td></tr></table>{{#if notes}}<div style="margin-top:16px"><strong>Notes:</strong> {{notes}}</div>{{/if}}{{#if shipping_instructions}}<div style="margin-top:8px"><strong>Shipping:</strong> {{shipping_instructions}}</div>{{/if}}', '{{company_name}} | PO {{po_number}}', 'letter', 'portrait', 1),
('quote', 'Quote', '<div style="color:#dc2626;font-size:10pt;margin-bottom:4px">QUOTE — Not a Tax Invoice</div><table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold">QUOTE</div><div style="font-size:13pt">#{{quote_number}}</div></td></tr></table><table style="margin-bottom:16px"><tr><td><div style="color:#555;font-size:9pt">Customer</div><strong>{{customer_name}}</strong></td><td><div style="color:#555;font-size:9pt">Quote Date</div>{{quote_date}}</td><td><div style="color:#555;font-size:9pt">Expires</div>{{expiration_date}}</td></tr></table><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0;border-bottom:2px solid #ccc"><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:right;padding:5px">Qty</th><th style="text-align:right;padding:5px">Price</th><th style="text-align:right;padding:5px">Extended</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="text-align:right;padding:5px">{{quantity}}</td><td style="text-align:right;padding:5px">${{unit_price}}</td><td style="text-align:right;padding:5px">${{extended}}</td></tr>{{/each}}</tbody></table><table style="width:40%;margin-left:auto;margin-top:12px"><tr style="border-top:2px solid #333"><td style="font-weight:bold">Total</td><td style="text-align:right;font-weight:bold">${{total}}</td></tr></table>', '{{company_name}} | Quote {{quote_number}}', 'letter', 'portrait', 1),
('packing_slip', 'Packing Slip', '<table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold">PACKING SLIP</div><div style="font-size:13pt">#{{shipment_number}}</div></td></tr></table><div style="margin-bottom:16px"><div style="color:#555;font-size:9pt">SHIP TO</div><strong>{{ship_to_name}}</strong><br>{{ship_to_address}}</div><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0;border-bottom:2px solid #ccc"><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:left;padding:5px">Lot</th><th style="text-align:right;padding:5px">Qty</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="padding:5px">{{lot_number}}</td><td style="text-align:right;padding:5px">{{quantity}}</td></tr>{{/each}}</tbody></table><div style="margin-top:40px">Received by: _________________________ Date: _____________</div>', '{{company_name}} | Packing Slip {{shipment_number}}', 'letter', 'portrait', 1),
('bill_of_lading', 'Bill of Lading', '<table style="margin-bottom:20px"><tr><td><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold">BILL OF LADING</div>#{{shipment_number}}</td></tr></table><table style="margin-bottom:16px"><tr><td style="width:50%"><div style="color:#555;font-size:9pt">CONSIGNEE</div><strong>{{ship_to_name}}</strong><br>{{ship_to_address}}</td><td><div style="color:#555;font-size:9pt">CARRIER</div>{{ship_via}}<br>Tracking: {{tracking_number}}</td></tr></table><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0"><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:left;padding:5px">Lot</th><th style="text-align:right;padding:5px">Qty</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="padding:5px">{{lot_number}}</td><td style="text-align:right;padding:5px">{{quantity}}</td></tr>{{/each}}</tbody></table>', '{{company_name}} | BOL {{shipment_number}}', 'letter', 'portrait', 1),
('order_acknowledgment', 'Order Acknowledgment', '<table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold">ORDER ACKNOWLEDGMENT</div>#{{so_number}}</td></tr></table><table style="margin-bottom:16px"><tr><td><div style="color:#555;font-size:9pt">Customer</div><strong>{{customer_name}}</strong></td><td><div style="color:#555;font-size:9pt">Order Date</div>{{order_date}}</td><td><div style="color:#555;font-size:9pt">Ship Date</div>{{promised_ship_date}}</td></tr></table><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0"><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:right;padding:5px">Qty</th><th style="text-align:right;padding:5px">Price</th><th style="text-align:right;padding:5px">Extended</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="text-align:right;padding:5px">{{quantity}}</td><td style="text-align:right;padding:5px">${{unit_price}}</td><td style="text-align:right;padding:5px">${{extended}}</td></tr>{{/each}}</tbody></table><table style="width:40%;margin-left:auto;margin-top:12px"><tr style="border-top:2px solid #333"><td style="font-weight:bold">Total</td><td style="text-align:right;font-weight:bold">${{total}}</td></tr></table>', '{{company_name}} | Order Acknowledgment {{so_number}}', 'letter', 'portrait', 1),
('proforma_invoice', 'Proforma Invoice', '<div style="color:#555;font-size:10pt;margin-bottom:4px">PROFORMA INVOICE — NOT A TAX INVOICE</div><table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:16pt;font-weight:bold">PROFORMA</div>#{{so_number}}</td></tr></table><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0"><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:right;padding:5px">Qty</th><th style="text-align:right;padding:5px">Price</th><th style="text-align:right;padding:5px">Extended</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="text-align:right;padding:5px">{{quantity}}</td><td style="text-align:right;padding:5px">${{unit_price}}</td><td style="text-align:right;padding:5px">${{extended}}</td></tr>{{/each}}</tbody></table><table style="width:40%;margin-left:auto;margin-top:12px"><tr style="border-top:2px solid #333"><td style="font-weight:bold">Total</td><td style="text-align:right;font-weight:bold">${{total}}</td></tr></table>', 'Proforma — {{so_number}}', 'letter', 'portrait', 1),
('coa', 'Certificate of Analysis', '<div style="text-align:center;margin-bottom:20px"><strong style="font-size:14pt">{{company_name}}</strong><div style="font-size:18pt;font-weight:bold;margin-top:8px">Certificate of Analysis</div></div><table style="margin-bottom:16px"><tr><td><strong>Item:</strong> {{item_code}}</td><td><strong>Description:</strong> {{item_description}}</td></tr><tr><td><strong>Batch/Lot:</strong> {{batch_number}}</td><td><strong>Date Produced:</strong> {{date_produced}}</td></tr><tr><td><strong>Quantity:</strong> {{quantity_produced}}</td><td><strong>QC Status:</strong> {{qc_status}}</td></tr></table>{{#if has_tests}}<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0"><th style="text-align:left;padding:5px">Test</th><th style="text-align:left;padding:5px">Specification</th><th style="text-align:left;padding:5px">Result</th><th style="padding:5px">Pass/Fail</th></tr></thead><tbody>{{#each tests}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{test_name}}</td><td style="padding:5px">{{spec}}</td><td style="padding:5px">{{result}}</td><td style="padding:5px">{{pass_fail}}</td></tr>{{/each}}</tbody></table>{{/if}}<div style="margin-top:40px"><table style="width:60%"><tr><td style="border-bottom:1px solid #333;padding:8px 0">Released By:</td><td style="width:30px"></td><td style="border-bottom:1px solid #333;padding:8px 0">Date:</td></tr></table></div>', '{{company_name}} | COA {{batch_number}}', 'letter', 'portrait', 1),
('scar', 'Supplier Corrective Action Request', '<table style="margin-bottom:20px"><tr><td><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:16pt;font-weight:bold;color:#dc2626">SCAR</div>#{{scar_number}}</td></tr></table><table style="margin-bottom:16px"><tr><td><strong>Supplier:</strong> {{supplier_name}}</td><td><strong>Issue Date:</strong> {{issue_date}}</td><td><strong>Due Date:</strong> {{due_date}}</td></tr></table><div style="margin-bottom:16px"><strong>Description:</strong><p>{{description}}</p></div><div style="margin-bottom:16px"><strong>Required Action:</strong><p>{{required_action}}</p></div>{{#if supplier_response}}<div style="margin-bottom:16px;padding:8px;background:#eff6ff"><strong>Supplier Response:</strong><p>{{supplier_response}}</p></div>{{/if}}', '{{company_name}} | SCAR {{scar_number}}', 'letter', 'portrait', 1),
('credit_memo', 'Credit Memo', '<table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold;color:#dc2626">CREDIT MEMO</div>#{{cm_number}}</td></tr></table><table style="margin-bottom:16px"><tr><td><div style="color:#555;font-size:9pt">Customer</div><strong>{{customer_name}}</strong><br>{{billing_address}}</td><td><div style="color:#555;font-size:9pt">RMA Reference</div>{{rma_number}}<br><div style="color:#555;font-size:9pt">Reason</div>{{return_reason}}</td></tr></table><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0"><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:right;padding:5px">Qty</th><th style="padding:5px">Disposition</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0"><td style="padding:5px">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="text-align:right;padding:5px">{{quantity}}</td><td style="padding:5px">{{disposition}}</td></tr>{{/each}}</tbody></table><div style="margin-top:16px;font-size:14pt;font-weight:bold">Total Credit: ${{credit_total}}</div>', '{{company_name}} | Credit Memo {{cm_number}}', 'letter', 'portrait', 1),
('batch_ticket', 'Batch Ticket', '<table style="margin-bottom:20px"><tr><td style="width:60%"><strong style="font-size:14pt">{{company_name}}</strong></td><td style="text-align:right"><div style="font-size:18pt;font-weight:bold">BATCH TICKET</div>#{{batch_number}}</td></tr></table>{{#if is_rush}}<div style="color:#dc2626;font-weight:bold;font-size:14pt;text-align:center;border:2px solid #dc2626;padding:8px;margin-bottom:12px">*** RUSH ***</div>{{/if}}<table style="margin-bottom:16px"><tr><td><strong>Item:</strong> {{item_code}} — {{item_description}}</td><td><strong>Recipe:</strong> {{recipe_version}}</td></tr><tr><td><strong>Target:</strong> {{target_quantity}}</td><td><strong>Facility:</strong> {{facility_name}}</td></tr><tr><td><strong>Scheduled:</strong> {{scheduled_date}}</td><td><strong>Assigned:</strong> {{assigned_to}}</td></tr></table>{{#if internal_notes}}<div style="padding:8px;background:#fef9c3;border:1px solid #fde68a;margin-bottom:12px"><strong>Notes:</strong> {{internal_notes}}</div>{{/if}}<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#f0f0f0"><th style="text-align:left;padding:5px">#</th><th style="text-align:left;padding:5px">Item</th><th style="text-align:left;padding:5px">Description</th><th style="text-align:right;padding:5px">Qty</th><th style="padding:5px">UOM</th><th style="padding:5px;width:80px">Actual</th></tr></thead><tbody>{{#each lines}}<tr style="border-bottom:1px solid #e0e0e0;height:28px"><td style="padding:5px">{{line_num}}</td><td style="padding:5px;font-weight:bold">{{item_code}}</td><td style="padding:5px">{{description}}</td><td style="text-align:right;padding:5px">{{quantity}}</td><td style="padding:5px">{{uom}}</td><td style="padding:5px"></td></tr>{{/each}}</tbody></table>', '{{company_name}} | Batch {{batch_number}}', 'letter', 'portrait', 1);
INSERT IGNORE INTO schema_migrations (migration_name) VALUES ('0020_document_templates_schema');
