-- Restructure document_templates for template editor
ALTER TABLE document_templates
    ADD COLUMN template_key VARCHAR(100) NULL UNIQUE AFTER id,
    ADD COLUMN template_name VARCHAR(150) NULL AFTER template_key,
    ADD COLUMN subject_template VARCHAR(255) NULL AFTER template_name,
    ADD COLUMN html_content LONGTEXT NULL AFTER subject_template,
    ADD COLUMN footer_html TEXT NULL AFTER html_content,
    ADD COLUMN page_size ENUM('letter','a4') NOT NULL DEFAULT 'letter' AFTER footer_html,
    ADD COLUMN page_orientation ENUM('portrait','landscape') NOT NULL DEFAULT 'portrait' AFTER page_size;

